package coreapi

import (
	"context"
	"errors"
	"fmt"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

// apiBasePath is appended to the control-plane origin to reach the v1
// surface. The generated spec's single server entry is "/api/v1", so the
// origin we dial is <core-host> and the client base is <core-host>/api/v1.
const apiBasePath = "/api/v1"

// New returns a *Client wired to talk to the Entire control plane (Core
// API) as the currently logged-in user.
//
// The base URL is the auth/login host — the Core API is served at
// <auth-host>/api/v1, and that host is exactly what `entire login`
// authenticated against, so no extra configuration is needed. Override
// with ENTIRE_AUTH_BASE_URL for non-default deployments (the same knob
// `entire login` honours).
//
// Auth is the logged-in bearer, resolved lazily per request through
// auth.TokenForResource so an RFC 8693 token exchange happens
// transparently when the stored token's audience doesn't already cover
// the control-plane host.
func New() (*Client, error) {
	base := strings.TrimRight(api.AuthBaseURL(), "/")
	// The token exchange's resource must be the bare origin; api.OriginOnly
	// strips any path/query so the audience the manager keys on matches
	// what the server expects.
	src := &bearerSource{resourceBaseURL: api.OriginOnly(base)}
	client, err := NewClient(base+apiBasePath, src)
	if err != nil {
		return nil, fmt.Errorf("build core API client: %w", err)
	}
	return client, nil
}

// bearerSource implements the generated SecuritySource, supplying the
// logged-in user's bearer token for every request. The control plane
// only uses bearerAuth from the CLI; the sessionAuth (browser cookie)
// scheme is satisfied with an empty value so ogen's two-scheme security
// requirement is met without sending a cookie.
type bearerSource struct {
	resourceBaseURL string
}

func (b *bearerSource) BearerAuth(ctx context.Context, _ OperationName) (BearerAuth, error) {
	token, err := auth.TokenForResource(ctx, b.resourceBaseURL)
	if err != nil {
		// Only suggest login when the user genuinely isn't logged in.
		// Other failures (STS rejection, network, malformed config) must
		// surface verbatim rather than be masked by a login hint.
		if errors.Is(err, auth.ErrNotLoggedIn) {
			return BearerAuth{}, fmt.Errorf("not logged in — run 'entire login': %w", err)
		}
		return BearerAuth{}, fmt.Errorf("resolve control-plane token: %w", err)
	}
	return BearerAuth{Token: token}, nil
}

func (b *bearerSource) SessionAuth(context.Context, OperationName) (SessionAuth, error) {
	// The CLI authenticates with a bearer token, never the browser
	// session cookie. Returning an empty value lets ogen satisfy the
	// "bearerAuth OR sessionAuth" requirement via the bearer alone.
	return SessionAuth{}, nil
}

// APIError reports the title/detail/status of a control-plane RFC 7807
// problem response, or "" if err isn't a control-plane API error. Use it
// to render a clean message instead of ogen's wrapped decode string:
//
//	if _, err := client.CreateOrg(ctx, body); err != nil {
//	    if msg := coreapi.APIError(err); msg != "" {
//	        return cli.NewSilentError(errors.New(msg))
//	    }
//	    return err
//	}
func APIError(err error) string {
	var statusErr *ErrorModelStatusCode
	if !errors.As(err, &statusErr) {
		return ""
	}
	m := statusErr.Response
	switch {
	case m.Detail.Set && m.Detail.Value != "":
		return m.Detail.Value
	case m.Title.Set && m.Title.Value != "":
		return m.Title.Value
	default:
		return fmt.Sprintf("control-plane request failed with status %d", statusErr.StatusCode)
	}
}

package coreapi

import (
	"errors"
	"fmt"
	"testing"
)

func TestAPIError(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		err  error
		want string
	}{
		{
			name: "nil error",
			err:  nil,
			want: "",
		},
		{
			name: "non-API error returns empty",
			err:  errors.New("dial tcp: connection refused"),
			want: "",
		},
		{
			name: "prefers detail",
			err: &ErrorModelStatusCode{
				StatusCode: 409,
				Response: ErrorModel{
					Title:  NewOptString("Conflict"),
					Detail: NewOptString("organization name already taken"),
				},
			},
			want: "organization name already taken",
		},
		{
			name: "falls back to title when detail empty",
			err: &ErrorModelStatusCode{
				StatusCode: 403,
				Response:   ErrorModel{Title: NewOptString("Forbidden")},
			},
			want: "Forbidden",
		},
		{
			name: "falls back to status when title and detail empty",
			err:  &ErrorModelStatusCode{StatusCode: 500},
			want: "control-plane request failed with status 500",
		},
		{
			name: "unwraps a wrapped API error",
			err: fmt.Errorf("create org: %w", &ErrorModelStatusCode{
				StatusCode: 422,
				Response:   ErrorModel{Detail: NewOptString("name is required")},
			}),
			want: "name is required",
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			if got := APIError(tc.err); got != tc.want {
				t.Errorf("APIError() = %q, want %q", got, tc.want)
			}
		})
	}
}

//go:build ignore

// Command normalize rewrites the fetched Core API spec into a form the Go
// client generator (ogen) turns into an ergonomic client. It reads the
// pristine upstream spec (core.openapi.json) and writes a generated,
// committed artifact (core.gen.json) that ogen consumes; the upstream
// file is never mutated, so a refresh is a clean `curl` overwrite.
//
// This command applies one transform, documented below. It is a deliberate
// codegen-ergonomics fold, not a bug workaround — the upstream spec is
// otherwise accurate (it declares real success codes and non-nullable
// arrays). The running checklist of upstream fixes lives in
// internal/coreapi/UPSTREAM.md.
//
// Fold every operation's explicit error responses (4xx/5xx) into a single
// "default" error, leaving the real success response (201 for creates, 200
// for reads, 204 for deletes) untouched. The spec declares accurate success
// codes but enumerates each error status separately with no "default"; ogen
// turns that into a per-operation sum type that forces a type switch at
// every call site. All error responses reference the same ErrorModel, so
// folding them into one "default" is lossless and flips ogen into
// "convenient errors": `(*T, error)` with any non-2xx as a typed
// `*ErrorModelStatusCode`. Keeping the literal success code (rather than a
// "2XX" range) means ogen returns the success type directly — no
// `*…StatusCode` wrapper to unwrap. This stays until/unless the spec grows
// a shared "default" response.
//
// Run via `go generate ./internal/coreapi/...` (the first generate step in
// gen.go), or by hand after refreshing the spec:
//
//	curl -fsSL https://us.console.entire.io/api/v1/openapi.json \
//	    -o internal/coreapi/spec/core.openapi.json
//	go run spec/normalize.go
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
)

const (
	srcPath = "spec/core.openapi.json"
	outPath = "spec/core.gen.json"
)

// errorModelRef is the component schema every problem+json error response
// in this spec already points at; the injected default reuses it.
const errorModelRef = "#/components/schemas/ErrorModel"

func main() {
	if err := run(); err != nil {
		fmt.Fprintf(os.Stderr, "normalize: %v\n", err)
		os.Exit(1)
	}
}

func run() error {
	raw, err := os.ReadFile(srcPath)
	if err != nil {
		return fmt.Errorf("read spec: %w", err)
	}

	var doc map[string]any
	if err := json.Unmarshal(raw, &doc); err != nil {
		return fmt.Errorf("parse spec: %w", err)
	}

	ops := foldErrorResponses(doc)

	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetIndent("", "  ")
	enc.SetEscapeHTML(false)
	if err := enc.Encode(doc); err != nil {
		return fmt.Errorf("encode spec: %w", err)
	}
	if err := os.WriteFile(outPath, buf.Bytes(), 0o644); err != nil { //nolint:gosec // spec is not a secret
		return fmt.Errorf("write spec: %w", err)
	}

	fmt.Printf("normalize: folded error responses on %d operation(s) → %s\n", ops, outPath)
	return nil
}

// httpMethods is the set of OpenAPI path-item keys that are operations.
var httpMethods = map[string]bool{
	"get": true, "put": true, "post": true, "delete": true,
	"options": true, "head": true, "patch": true, "trace": true,
}

// foldErrorResponses rewrites each operation's responses to its real 2xx
// success entries plus a single "default" error, dropping the explicit
// 4xx/5xx codes.
//
// The spec declares accurate success codes (201 for creates, 200 for
// reads, 204 for deletes), so those are kept verbatim — keeping the literal
// code (not a "2XX" range) means ogen returns the success type directly, with no
// `*…StatusCode` wrapper. Every explicit error status references the same
// ErrorModel, so folding them all into one "default" is lossless and flips
// ogen into "convenient errors": `(*T, error)` with any non-2xx as a typed
// `*ErrorModelStatusCode`. Returns the number of operations rewritten.
func foldErrorResponses(doc map[string]any) int {
	paths, ok := doc["paths"].(map[string]any)
	if !ok {
		return 0
	}
	count := 0
	for _, item := range paths {
		pathItem, ok := item.(map[string]any)
		if !ok {
			continue
		}
		for method, op := range pathItem {
			if !httpMethods[method] {
				continue
			}
			operation, ok := op.(map[string]any)
			if !ok {
				continue
			}
			responses, ok := operation["responses"].(map[string]any)
			if !ok {
				continue
			}
			folded := map[string]any{"default": defaultErrorResponse()}
			for status, resp := range responses {
				if len(status) > 0 && status[0] == '2' {
					folded[status] = resp
				}
			}
			operation["responses"] = folded
			count++
		}
	}
	return count
}

func defaultErrorResponse() map[string]any {
	return map[string]any{
		"description": "Error",
		"content": map[string]any{
			"application/problem+json": map[string]any{
				"schema": map[string]any{"$ref": errorModelRef},
			},
		},
	}
}

// Package coreapi is a generated client for the Entire Core API — the
// control plane that manages identity, orgs, projects, repos, mirrors,
// and service accounts.
//
// The oas_*.go files are generated by ogen from spec/core.gen.json (the
// normalised spec produced by spec/normalize.go from the pristine
// upstream spec/core.openapi.json). Do not edit them by hand. To refresh:
//
//	curl -fsSL https://us.console.entire.io/api/v1/openapi.json \
//	    -o internal/coreapi/spec/core.openapi.json
//	go generate ./internal/coreapi/...
//
// The hand-written authenticated constructor and error helpers live in
// client.go alongside the generated code.
package coreapi

//go:generate go run spec/normalize.go
//go:generate go run github.com/ogen-go/ogen/cmd/ogen@v1.20.3 --target . --package coreapi --config ogen.yml --clean spec/core.gen.json

