1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"strings"
10	
11		"charm.land/lipgloss/v2"
12		"github.com/spf13/cobra"
13	
14		"github.com/entireio/cli/cmd/entire/cli/auth"
15		"github.com/entireio/cli/internal/coreapi"
16	)
17	
18	// addControlPlaneFlags registers the persistent flags shared by every
19	// control-plane command group. Persistent so they're inherited by nested
20	// subcommands (e.g. `entire repo mirror list`):
21	//   - --json: emit the raw wire JSON instead of the default human table.
22	//   - --insecure-http-auth: permit the token exchange over plain http://
23	//     (local/dev deployments where the core isn't behind TLS). Hidden, as
24	//     elsewhere in the CLI.
25	func addControlPlaneFlags(cmd *cobra.Command) {
26		cmd.PersistentFlags().Bool("json", false, "output raw JSON instead of a table")
27		cmd.PersistentFlags().Bool("insecure-http-auth", false, "Allow authentication over plain HTTP (insecure, for local development only)")
28		if err := cmd.PersistentFlags().MarkHidden("insecure-http-auth"); err != nil {
29			panic(fmt.Sprintf("hide insecure-http-auth flag: %v", err))
30		}
31	}
32	
33	// jsonRequested reports whether --json was set on cmd or an ancestor. A
34	// lookup error means the flag isn't defined on this command tree, which is
35	// treated as "not requested".
36	func jsonRequested(cmd *cobra.Command) bool {
37		v, err := cmd.Flags().GetBool("json")
38		return err == nil && v
39	}
40	
41	// insecureHTTPRequested reports whether --insecure-http-auth was set on cmd
42	// or an ancestor.
43	func insecureHTTPRequested(cmd *cobra.Command) bool {
44		v, err := cmd.Flags().GetBool("insecure-http-auth")
45		return err == nil && v
46	}
47	
48	// runCoreList fetches a slice via fn and renders it as an aligned table
49	// (default) or the raw wire JSON (--json). headers names the columns; row
50	// maps one item to its cells in the same order. The human view keeps the
51	// output actionable — only the columns a person acts on — while --json
52	// preserves the full model for scripting.
53	func runCoreList[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) ([]T, error)) error {
54		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
55			items, err := fn(ctx, c)
56			if err != nil {
57				return err
58			}
59			if jsonRequested(cmd) {
60				return printJSON(cmd.OutOrStdout(), items)
61			}
62			if len(items) == 0 {
63				fmt.Fprintln(cmd.ErrOrStderr(), "(none)")
64				return nil
65			}
66			return printTable(cmd.OutOrStdout(), headers, items, row)
67		})
68	}
69	
70	// runCoreObject fetches a single value via fn and renders it as a vertical
71	// field/value list (default) or raw JSON (--json), reusing the same column
72	// definition as the matching list view.
73	func runCoreObject[T any](cmd *cobra.Command, headers []string, row func(T) []string, fn func(ctx context.Context, c *coreapi.Client) (*T, error)) error {
74		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
75			item, err := fn(ctx, c)
76			if err != nil {
77				return err
78			}
79			if jsonRequested(cmd) {
80				return printJSON(cmd.OutOrStdout(), item)
81			}
82			return printFields(cmd.OutOrStdout(), headers, row(*item))
83		})
84	}
85	
86	// tableStyles holds the foreground styles for the human table/field views,
87	// matching the activity/session palette: gray ("8") for headers and
88	// secondary cells, white ("7") for the primary (first-column) value. When
89	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
90	// styles are no-ops and output is plain.
91	type tableStyles struct {
92		enabled bool
93		header  lipgloss.Style
94		primary lipgloss.Style
95		cell    lipgloss.Style
96	}
97	
98	func newTableStyles(w io.Writer) tableStyles {
99		if !shouldUseColor(w) {
100			return tableStyles{}
101		}
102		return tableStyles{
103			enabled: true,
104			header:  lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true),
105			primary: lipgloss.NewStyle().Foreground(lipgloss.Color("7")),
106			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
107		}
108	}
109	
110	// style applies s to text only when color is enabled; otherwise it returns
111	// text unchanged so padding math and plain output stay correct.
112	func (t tableStyles) style(s lipgloss.Style, text string) string {
113		if !t.enabled {
114			return text
115		}
116		return s.Render(text)
117	}
118	
119	// columnStyle picks the foreground for a data cell: the first column is the
120	// primary identifier (white), the rest are secondary (gray).
121	func (t tableStyles) columnStyle(col int) lipgloss.Style {
122		if col == 0 {
123			return t.primary
124		}
125		return t.cell
126	}
127	
128	// printTable writes headers plus one row per item, columns aligned on the
129	// plain-text widths so ANSI color codes don't throw off the layout (they're
130	// applied after padding). Callers handle the empty case.
131	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
132		st := newTableStyles(w)
133		rows := make([][]string, len(items))
134		for i, it := range items {
135			rows[i] = row(it)
136		}
137		widths := columnWidths(headers, rows)
138	
139		var b strings.Builder
140		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
141		for _, r := range rows {
142			writeTableRow(&b, r, widths, st.columnStyle, st)
143		}
144		if _, err := io.WriteString(w, b.String()); err != nil {
145			return fmt.Errorf("render table: %w", err)
146		}
147		return nil
148	}
149	
150	// printFields writes a single record as aligned "FIELD  value" lines: the
151	// label in header gray, the value in the same primary/secondary color the
152	// list view would give that column.
153	func printFields(w io.Writer, headers, values []string) error {
154		st := newTableStyles(w)
155		labelWidth := 0
156		for _, h := range headers {
157			if n := lipgloss.Width(h); n > labelWidth {
158				labelWidth = n
159			}
160		}
161		var b strings.Builder
162		for i, h := range headers {
163			var v string
164			if i < len(values) {
165				v = values[i]
166			}
167			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
168			b.WriteString(label)
169			b.WriteString("  ")
170			b.WriteString(st.style(st.columnStyle(i), v))
171			b.WriteByte('\n')
172		}
173		if _, err := io.WriteString(w, b.String()); err != nil {
174			return fmt.Errorf("render fields: %w", err)
175		}
176		return nil
177	}
178	
179	// columnWidths returns the max plain-text width of each column across the
180	// headers and all rows.
181	func columnWidths(headers []string, rows [][]string) []int {
182		widths := make([]int, len(headers))
183		for i, h := range headers {
184			widths[i] = lipgloss.Width(h)
185		}
186		for _, r := range rows {
187			for i, c := range r {
188				if i < len(widths) && lipgloss.Width(c) > widths[i] {
189					widths[i] = lipgloss.Width(c)
190				}
191			}
192		}
193		return widths
194	}
195	
196	// writeTableRow pads each cell to its column width on the plain text, then
197	// styles it — so alignment is computed before any ANSI codes are added.
