1	package auth
2	
3	import (
4		"bytes"
5		"context"
6		"io"
7		"net/http"
8		"net/url"
9		"strings"
10		"testing"
11	
12		"github.com/entireio/cli/cmd/entire/cli/api"
13	)
14	
15	// captureTransport records the last request's parsed form body and
16	// returns a canned RFC 8693 token-exchange success response.
17	type captureTransport struct {
18		form url.Values
19		url  string
20	}
21	
22	func (c *captureTransport) RoundTrip(req *http.Request) (*http.Response, error) {
23		body, err := io.ReadAll(req.Body)
24		if err != nil {
25			return nil, err
26		}
27		form, err := url.ParseQuery(string(body))
28		if err != nil {
29			return nil, err
30		}
31		c.form = form
32		c.url = req.URL.String()
33		resp := `{"access_token":"repo-scoped.jwt","token_type":"Bearer",` +
34			`"issued_token_type":"urn:ietf:params:oauth:token-type:access_token","expires_in":300}`
35		return &http.Response{
36			StatusCode: http.StatusOK,
37			Header:     http.Header{"Content-Type": []string{"application/json"}},
38			Body:       io.NopCloser(bytes.NewBufferString(resp)),
39			Request:    req,
40		}, nil
41	}
42	
43	// fakeBackend returns a fixed login token for any keyring lookup so the
44	// exchange has a subject token without touching the OS keyring.
45	type fakeBackend struct{ token string }
46	
47	func (f fakeBackend) save(string, string, string) error  { return nil }
48	func (f fakeBackend) get(string, string) (string, error) { return f.token, nil }
49	func (f fakeBackend) delete(string, string) error        { return nil }
50	
51	func TestRepoScopedToken_WireForm(t *testing.T) {
52		t.Setenv(api.AuthBaseURLEnvVar, "https://us.auth.entire.io")
53	
54		prevBackend := chooseBackend
55		chooseBackend = func() tokenBackend { return fakeBackend{token: "login.jwt.value"} }
56		t.Cleanup(func() { chooseBackend = prevBackend })
57	
58		capture := &captureTransport{}
59		t.Cleanup(SetRepoExchangeTransportForTest(capture))
