type experimentalCommandInfo struct {
	Name       string
	Invocation string
	Summary    string
}

var experimentalCommands = []experimentalCommandInfo{
	{
		Name:       "review",
		Invocation: "entire review",
		Summary:    "Run configured review skills against the current branch",
	},
	{
		Name:       "investigate",
